
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_sb98_1a_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_sb98_1a", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.586856349933801e+00, -3.516816832294970e+00, -3.418722231511992e+00, -3.282937691989269e+00, -3.098130276722564e+00, -2.852640106989432e+00, -2.537749724133700e+00, -2.153746506168012e+00, -1.718747691936532e+00, -1.274466456066524e+00, -8.607509420364686e-01, -5.879185604257640e-01, -5.057084283663548e-01, -4.167526418013924e-01, -2.973777044618362e-01, -1.812003821044351e-01, -1.017133796867437e-01, -4.318457337509388e-02, -9.939720039479972e-03, -1.129217580881336e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


